# Check if there's symmetry
def has_horizontal_symmetry(grid):
    rows = len(grid)
    for r in range(rows // 2 + rows % 2):
        if r != rows - 1 - r:
            if grid[r] != grid[rows - 1 - r]:
                return False
    return True

def has_vertical_symmetry(grid):
    cols = len(grid[0])
    for c in range(cols // 2 + cols % 2):
        if c != cols - 1 - c:
            for r in range(rows):
                if grid[r][c] != grid[r][cols - 1 - c]:
                    return False
    return True

def has_point_symmetry(grid):
    rows, cols = len(grid), len(grid[0])
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] != grid[rows - 1 - r][cols - 1 - c]:
                return False
    return True

print(f"Horizontal symmetry: {has_horizontal_symmetry(grid)}")
print(f"Vertical symmetry: {has_vertical_symmetry(grid)}")
print(f"Point symmetry: {has_point_symmetry(grid)}")

